### 2. `FileExplorerPanel.vue` — add `workspace` prop, pass root down

```vue src/components/filebrowser/FileExplorerPanel.vue
<script setup>
import FileExplorer from './FileExplorer.vue'
import TabManager from './TabManager.vue'
import VerticalSplitter from '../layout/VerticalSplitter.vue'
</script>

<template>
  <VerticalSplitter :panels="splitterConfig">
    <template #left>
      <!-- CHANGED: pass workspace.folder_path as root when workspace prop is provided -->
      <FileExplorer :root="workspaceRoot" @open="handleFileOpen" />
    </template>

    <template #right>
      <TabManager class="pr-1" ref="tabManager" />
    </template>
  </VerticalSplitter>
</template>

<script>
export default {
  name: 'FileExplorerPanel',
  props: {
    // ADDED: optional workspace to scope the file explorer to workspace.folder_path
    workspace: {
      type: Object,
      default: null
    }
  },
  data() {
    return {
      splitterConfig: {
        left: {
          minSize: 15,
          defaultSize: 25,
          collapsible: true
        },
        right: {
          minSize: 15,
          defaultSize: 75,
          collapsible: true
        }
      }
    }
  },
  computed: {
    // ADDED: resolve root path from workspace or leave null (FileExplorer falls back to project root)
    workspaceRoot() {
      return this.workspace?.folder_path || null
    }
  },
  methods: {
    handleFileOpen(fileData) {
      this.$refs.tabManager.addTab({
        path: fileData.path,
        name: fileData.name
      })
    }
  }
}
</script>
